"""Invariants of the consumer registry / dependency graph generated by scripts/analysis/consumer_graph.py."""
import json
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
STATUSES = {"verified", "mismatched", "broken", "unverified"}
BASES = {"ast", "ast+file", "absence", "config", "none", "static_text"}


@pytest.fixture(scope="module")
def reg(tmp_path_factory):
    out = tmp_path_factory.mktemp("cg")
    subprocess.run([sys.executable, str(ROOT / "scripts/analysis/consumer_graph.py"), "--out", str(out)], check=True, capture_output=True, cwd=ROOT)
    return json.loads((out / "consumer_registry.json").read_text())


def test_all_35_features_in_canonical_order(reg):
    from features.feature_schema import CANONICAL_FEATURES
    assert [f["name"] for f in reg["features"]] == list(CANONICAL_FEATURES)


def test_every_edge_has_known_endpoints_basis_and_evidence(reg):
    ids = {n["id"] for n in reg["nodes"]}
    for e in reg["edges"]:
        assert e["src"] in ids and e["dst"] in ids
        assert e["established_by"] in BASES and e["evidence"]


def test_every_branch_has_the_contract_fields_and_a_valid_status(reg):
    need = {"producer", "transformation", "consumer", "contract_identity", "dependency_path", "parity_evidence", "status", "required_tests", "acceptance"}
    for b in reg["branches"]:
        assert need <= set(b) and b["status"] in STATUSES and b["parity_evidence"]


def test_verified_requires_complete_dependency_path(reg):
    for b in reg["branches"]:
        if b["status"] == "verified" and b["dependency_path"]:
            assert b["path_complete"] is True, b["id"]


def test_known_defects_are_not_hidden(reg):
    st = {b["id"]: b["status"] for b in reg["branches"]}
    assert st["B1"] == "mismatched" and st["B2"] == "broken" and st["B4"] == "broken" and st["D1"] == "mismatched"
    live = {f["name"]: f["parity"]["live_hook_featurestore"] for f in reg["features"]}
    assert live["body_ratio"] == "value_mismatch" and live["session"] == "type_break" and live["rsi_14"] == "identical"


def test_no_feature_definition_contract_is_claimed(reg):
    assert reg["contract_state"]["feature_definition_contract_exists"] is False
